public class CPythonControlFlowTests
{
    [Theory]
    [InlineData("for i in range(3):\n    if i == 1:\n        continue\n    print(i)\nelse:\n    print('done')", "0\n2\ndone\n")]
    [InlineData("for i in range(5):\n    if i == 2:\n        break\n    print(i)\nelse:\n    print('no break')", "0\n1\n")]
    [InlineData("n = 0\nwhile n < 3:\n    n += 1\nelse:\n    print('while else', n)", "while else 3\n")]
    [InlineData("x = 7\nif x < 5:\n    print('small')\nelif x < 10:\n    print('medium')\nelse:\n    print('large')", "medium\n")]
    [InlineData("for i in range(2):\n    for j in range(3):\n        if j == 2:\n            break\n        print(i, j)", "0 0\n0 1\n1 0\n1 1\n")]
    [InlineData("i = 0\nwhile True:\n    i += 1\n    if i > 3:\n        break\nprint(i)", "4\n")]
    [InlineData("for x in []:\n    pass\nelse:\n    print('empty loop else')", "empty loop else\n")]
    [InlineData("print(list(range(10, 0, -3)), list(range(0)), len(range(5, 100, 7)), range(3)[-1], 5 in range(10))", "[10, 7, 4, 1] [] 14 2 True\n")]
    [InlineData("for i, c in enumerate('ab'):\n    for j in range(i + 1):\n        pass\n    print(i, c, j)", "0 a 0\n1 b 1\n")]
    [InlineData("x = 0\nif x:\n    print('yes')\nprint('end')", "end\n")]
    [InlineData("if True: print('one-liner'); print('two')", "one-liner\ntwo\n")]
    [InlineData("for i in range(3): print(i, end=' ')\nprint()", "0 1 2 \n")]
    [InlineData("total = 0\nfor i in range(1, 101):\n    if i % 3 == 0 or i % 5 == 0:\n        total += i\nprint(total)", "2418\n")]
    [InlineData("print(range(1, 10, 2), list(reversed(range(4))), range(10)[2:8:2])", "range(1, 10, 2) [3, 2, 1, 0] range(2, 8, 2)\n")]
    public void MatchesCPython(string code, string expected) => Assert.Equal(expected, PyRun.Out(code));
}

