    [InlineData("def make_counter():\n    count = 0\n    def inc():\n        nonlocal count\n        count += 1\n        return count\n    return inc\nc = make_counter()\nc(); c()\nprint(c())", "3\n")]
    [InlineData("x = 1\ndef f():\n    global x\n    x = 5\nf()\nprint(x)", "5\n")]
    [InlineData("x = 1\ndef f():\n    print(x)\n    x = 2\nf()", "!UnboundLocalError: cannot access local variable 'x' where it is not associated with a value")]
    [InlineData("fs = [lambda i=i: i * 10 for i in range(3)]\nprint([f() for f in fs])", "[0, 10, 20]\n")]
    [InlineData("fs = [lambda: i for i in range(3)]\nprint([f() for f in fs])", "[2, 2, 2]\n")]
    [InlineData("def fact(n):\n    return 1 if n <= 1 else n * fact(n - 1)\nprint(fact(20), fact(30))", "2432902008176640000 265252859812191058636308480000000\n")]
    [InlineData("def deco(fn):\n    def wrapper(*a, **k):\n        print('before')\n        r = fn(*a, **k)\n        print('after')\n        return r\n    return wrapper\n@deco\ndef add(a, b):\n    return a + b\nprint(add(2, 3))", "before\nafter\n5\n")]
    [InlineData("def repeat(n):\n    def deco(fn):\n        def w(*a):\n            return [fn(*a) for _ in range(n)]\n        return w\n    return deco\n@repeat(3)\ndef one():\n    return 1\nprint(one())", "[1, 1, 1]\n")]
    [InlineData("def f():\n    '''Docstring here.'''\n    return None\nprint(f.__doc__, f.__name__, f())", "Docstring here. f None\n")]
    [InlineData("def outer():\n    x = 'outer'\n    def middle():\n        def inner():\n            return x\n        return inner()\n    return middle()\nprint(outer())", "outer\n")]
    [InlineData("def f(a, b):\n    return a * b\ng = lambda *args: sum(args)\nprint(f(3, 4), g(1, 2, 3), (lambda: 'x')())", "12 6 x\n")]
    [InlineData("def f(l=[]):\n    l.append(1)\n    return l\nf()\nprint(f())", "[1, 1]\n")]
    [InlineData("def f(n):\n    if n == 0:\n        return\n    return n\nprint(f(0), f(3))", "None 3\n")]
    [InlineData("def gcd(a, b):\n    while b:\n        a, b = b, a % b\n    return a\nprint(gcd(48, 18), gcd(17, 5))", "6 1\n")]
    [InlineData("def f(**kw):\n    return sorted(kw.items())\nprint(f(b=2, a=1))", "[('a', 1), ('b', 2)]\n")]
    [InlineData("def f(a, b, c):\n    return a + b + c\nargs = (1, 2)\nprint(f(*args, 3), f(1, *[2], **{'c': 3}))", "6 6\n")]
    [InlineData("def f():\n    return 1, 2\na, b = f()\nprint(a, b, f())", "1 2 (1, 2)\n")]
    [InlineData("def f(x):\n    def g():\n        return x + 1\n    x = 10\n    return g()\nprint(f(0))", "11\n")]
    [InlineData("def counter():\n    counter.calls += 1\n    return counter.calls\ncounter.calls = 0\ncounter(); print(counter())", "2\n")]
    [InlineData("f = lambda x, y=2: x ** y\nprint(f(3), f(2, 5), f.__name__)", "9 32 <lambda>\n")]
