    [InlineData("class C:\n    count = 0\n    def __init__(self):\n        C.count += 1\n    @classmethod\n    def make(cls):\n        return cls()\n    @staticmethod\n    def helper(x):\n        return x * 2\nC(); C.make()\nprint(C.count, C.helper(5), C().helper(1))", "2 10 2\n")]
    [InlineData("class T:\n    def __init__(self):\n        self._t = 0\n    @property\n    def temp(self):\n        return self._t\n    @temp.setter\n    def temp(self, v):\n        if v < -273:\n            raise ValueError('too cold')\n        self._t = v\nt = T()\nt.temp = 25\nprint(t.temp)\nt.temp = -300", "25\n!ValueError: too cold")]
    [InlineData("class A:\n    pass\na = A()\na.x = 1\nprint(a.x, hasattr(a, 'y'), getattr(a, 'y', 'default'))\nsetattr(a, 'y', 2)\nprint(a.y, vars(a))", "1 False default\n2 {'x': 1, 'y': 2}\n")]
    [InlineData("class A:\n    pass\nprint(A().missing)", "!AttributeError: 'A' object has no attribute 'missing'")]
