    [InlineData("class A:\n    def who(self):\n        return 'A'\nclass B(A):\n    pass\nclass C(A):\n    def who(self):\n        return 'C'\nclass D(B, C):\n    pass\nprint(D().who(), [k.__name__ for k in D.__mro__])", "C ['D', 'B', 'C', 'A', 'object']\n")]
    [InlineData("class N:\n    def __init__(self, v):\n        self.v = v\n    def __mul__(self, o):\n        return N(self.v * (o.v if isinstance(o, N) else o))\n    def __rmul__(self, o):\n        return N(self.v * o)\n    def __neg__(self):\n        return N(-self.v)\n    def __bool__(self):\n        return self.v != 0\nprint((N(3) * 2).v, (2 * N(3)).v, (-N(4)).v, bool(N(0)), (N(2) * N(5)).v)", "6 6 -4 False 10\n")]
