public class CPythonExceptionsTests
{
    [Theory]
    [InlineData("try:\n    1 / 0\nexcept ZeroDivisionError as e:\n    print('caught', e)", "caught division by zero\n")]
    [InlineData("try:\n    int('x')\nexcept (TypeError, ValueError) as e:\n    print(type(e).__name__, e)", "ValueError invalid literal for int() with base 10: 'x'\n")]
    [InlineData("try:\n    pass\nexcept Exception:\n    print('no')\nelse:\n    print('else')\nfinally:\n    print('finally')", "else\nfinally\n")]
    [InlineData("def f():\n    try:\n        return 'try'\n    finally:\n        print('cleanup')\nprint(f())", "cleanup\ntry\n")]
    [InlineData("def f():\n    try:\n        return 1\n    finally:\n        return 2\nprint(f())", "2\n")]
    [InlineData("class MyErr(Exception):\n    pass\ntry:\n    raise MyErr('custom')\nexcept MyErr as e:\n    print('got', e, repr(e), e.args)", "got custom MyErr('custom') ('custom',)\n")]
    [InlineData("class AppError(Exception):\n    def __init__(self, code, msg):\n        super().__init__(msg)\n        self.code = code\ntry:\n    raise AppError(404, 'missing')\nexcept AppError as e:\n    print(e.code, e, e.args)", "404 missing ('missing',)\n")]
    [InlineData("try:\n    try:\n        {}['k']\n    except KeyError as e:\n        raise ValueError('wrapped') from e\nexcept ValueError as e:\n    print(e, type(e.__cause__).__name__, e.__cause__)", "wrapped KeyError 'k'\n")]
    [InlineData("try:\n    raise ValueError\nexcept ValueError as e:\n    print(repr(e), str(e) == '')", "ValueError() True\n")]
    [InlineData("def f():\n    raise TypeError('bad type')\ntry:\n    f()\nexcept Exception as e:\n    print(f'{type(e).__name__}: {e}')", "TypeError: bad type\n")]
    [InlineData("try:\n    x = [1][5]\nexcept LookupError as e:\n    print('lookup', e)", "lookup list index out of range\n")]
    [InlineData("try:\n    try:\n        raise KeyError('a')\n    finally:\n        print('inner finally')\nexcept KeyError as e:\n    print('outer', e)", "inner finally\nouter 'a'\n")]
    [InlineData("try:\n    raise RuntimeError('first')\nexcept RuntimeError:\n    try:\n        raise\n    except RuntimeError as e:\n        print('reraised', e)", "reraised first\n")]
    [InlineData("for i in range(3):\n    try:\n        if i == 1:\n            continue\n        print('body', i)\n    finally:\n        print('fin', i)", "body 0\nfin 0\nfin 1\nbody 2\nfin 2\n")]
    [InlineData("try:\n    raise Exception('a', 'b')\nexcept Exception as e:\n    print(e, e.args)", "('a', 'b') ('a', 'b')\n")]
    [InlineData("e = ValueError('x')\nprint(isinstance(e, Exception), isinstance(e, BaseException), issubclass(KeyError, LookupError))", "True True True\n")]
    [InlineData("assert 1 + 1 == 2, 'math works'\nassert False, 'boom'", "!AssertionError: boom")]
    [InlineData("assert 0", "!AssertionError: ")]
    [InlineData("raise ValueError('top level')", "!ValueError: top level")]
    [InlineData("raise 5", "!TypeError: exceptions must derive from BaseException")]
    [InlineData("try:\n    raise 'str'\nexcept TypeError as e:\n    print(e)", "exceptions must derive from BaseException\n")]
    [InlineData("import math\ntry:\n    math.sqrt(-1)\nexcept ValueError as e:\n    print(e)", "math domain error\n")]
    [InlineData("try:\n    undefined_thing\nexcept NameError as e:\n    print(e)", "name 'undefined_thing' is not defined\n")]
    [InlineData("try:\n    None.foo\nexcept AttributeError as e:\n    print(e)", "'NoneType' object has no attribute 'foo'\n")]
    [InlineData("try:\n    len(5)\nexcept TypeError as e:\n    print(e)", "object of type 'int' has no len()\n")]
    [InlineData("try:\n    raise StopIteration(5)\nexcept StopIteration as e:\n    print(e.value)", "5\n")]
    [InlineData("def risky(n):\n    if n < 0:\n        raise ValueError(f'negative: {n}')\n    return n\nresults = []\nfor v in [1, -2, 3]:\n    try:\n        results.append(risky(v))\n    except ValueError as e:\n        results.append(str(e))\nprint(results)", "[1, 'negative: -2', 3]\n")]
