public class CPythonMatchTests
{
    [Theory]
    [InlineData("def f(x):\n    match x:\n        case 0:\n            return 'zero'\n        case 1 | 2:\n            return 'small'\n        case int(n) if n < 0:\n            return 'negative'\n        case str():\n            return 'string'\n        case _:\n            return 'other'\nprint([f(v) for v in [0, 2, -5, 'a', 9.5]])", "['zero', 'small', 'negative', 'string', 'other']\n")]
    [InlineData("def f(p):\n    match p:\n        case (0, 0):\n            return 'origin'\n        case (x, 0):\n            return f'x={x}'\n        case [x, y, *rest]:\n            return f'{x},{y},{rest}'\n        case _:\n            return '?'\nprint(f((0, 0)), f((3, 0)), f([1, 2, 3, 4]), f([1]))", "origin x=3 1,2,[3, 4] ?\n")]
    [InlineData("def f(cmd):\n    match cmd:\n        case {'action': 'go', 'dir': d}:\n            return 'go ' + d\n        case {'action': a, **rest}:\n            return a + str(sorted(rest))\nprint(f({'action': 'go', 'dir': 'north'}), f({'action': 'stop', 'x': 1}))", "go north stop['x']\n")]
    [InlineData("class Point:\n    __match_args__ = ('x', 'y')\n    def __init__(self, x, y):\n        self.x, self.y = x, y\ndef where(p):\n    match p:\n        case Point(0, 0):\n            return 'origin'\n        case Point(x=0, y=y):\n            return f'on y axis at {y}'\n        case Point(x, y) if x == y:\n            return 'diagonal'\n        case Point():\n            return 'somewhere'\nprint(where(Point(0, 0)), where(Point(0, 5)), where(Point(2, 2)), where(Point(1, 3)))", "origin on y axis at 5 diagonal somewhere\n")]
    [InlineData("match [1, [2, 3]]:\n    case [a, [b, c] as inner]:\n        print(a, b, c, inner)", "1 2 3 [2, 3]\n")]
    [InlineData("x = None\nmatch x:\n    case None:\n        print('none')\n    case True:\n        print('true')", "none\n")]
    [InlineData("match = 5\nprint(match * 2)", "10\n")]
    [InlineData("match 'hello':\n    case 'hi' | 'hello' as greet:\n        print('greeting', greet)", "greeting hello\n")]
    public void MatchesCPython(string code, string expected) => Assert.Equal(expected, PyRun.Out(code));
}

