    [InlineData("class Meters(float):\n    def __str__(self):\n        return f'{float(self)} m'\nd = Meters(2.5)\nprint(d, repr(d), d * 2, type(d * 2).__name__, d + Meters(1), isinstance(d, float), round(d), int(d), f'{d:.1f}', f'{d}', d.is_integer(), Meters('1.25'))\nimport math\nprint(math.sqrt(Meters(4)), math.floor(Meters(2.7)), Meters(3) == 3.0, Meters(0.5).as_integer_ratio())", "2.5 m 2.5 5.0 float 3.5 True 2 2 2.5 2.5 m False 1.25 m\n2.0 2 True (1, 2)\n")]
    [InlineData("class F(float):\n    def __eq__(self, o):\n        return abs(self - o) < 0.01\n    __hash__ = float.__hash__\nprint(F(1.0) == 1.001, 1.001 == F(1.0), F(1.0) != 1.001, hash(F(2.0)) == hash(2.0), F(1.0) in [1.001])", "True True True True True\n")]
