    [InlineData("class N(int):\n    def __new__(cls, v, label='n'):\n        o = super().__new__(cls, v)\n        o.label = label\n        return o\n    def __radd__(self, other):\n        return 'radd ' + str(other)\nn = N(4, 'four')\nprint(n, n.label, 1 + n, n + 1, type(n).__mro__)", "4 four radd 1 5 (<class '__main__.N'>, <class 'int'>, <class 'object'>)\n")]
