    [InlineData("class I(int):\n    def __index__(self):\n        return 1\n    def __int__(self):\n        return 2\nx = I(5)\nprint(x, int(x), [0, 1, 2, 3, 4, 5][x], x + 0, x * 1)", "5 2 5 5 5\n")]
