public class CPythonSubclassContainersTests
{
    [Theory]
    [InlineData("class Point(tuple):\n    def __new__(cls, x, y):\n        return super().__new__(cls, (x, y))\n    @property\n    def x(self):\n        return self[0]\n    @property\n    def y(self):\n        return self[1]\n    def __repr__(self):\n        return f'Point({self[0]}, {self[1]})'\np = Point(1, 2)\na, b = p\nprint(p, p.x, p.y, len(p), p + (3,), type(p + (3,)).__name__, p == (1, 2), hash(p) == hash((1, 2)), list(p), a, b, type(p[0:1]).__name__)\nprint(sorted([Point(2, 1), Point(1, 2)]), str(p), [p], {p: 'here'}[(1, 2)], isinstance(p, tuple), p.count(1), p.index(2), max(p))", "Point(1, 2) 1 2 2 (1, 2, 3) tuple True True [1, 2] 1 2 tuple\n[Point(1, 2), Point(2, 1)] Point(1, 2) [Point(1, 2)] here True 1 1 2\n")]
    [InlineData("class T(tuple):\n    pass\nt = T([1, 2, 3])\nprint(t, type(t).__name__, T(), T('ab'), t * 2, type(t * 2).__name__, t[::-1], 2 in t, T(x for x in range(2)))", "(1, 2, 3) T () ('a', 'b') (1, 2, 3, 1, 2, 3) tuple (3, 2, 1) True (0, 1)\n")]
    [InlineData("class Stack(list):\n    def push(self, x):\n        self.append(x)\n    def peek(self):\n        return self[-1]\ns = Stack([1, 2])\ns.push(3)\nprint(s, len(s), s.peek(), isinstance(s, list), type(s).__name__, s + [4], type(s + [4]).__name__, s[1:], type(s[1:]).__name__, s == [1, 2, 3], sum(s), sorted(s, reverse=True))\nprint(Stack(), Stack('ab'), repr(Stack([1])), type(s.copy()).__name__, type(s * 2).__name__, list(reversed(s)), s.pop(), s)", "[1, 2, 3] 3 3 True Stack [1, 2, 3, 4] list [2, 3] list True 6 [3, 2, 1]\n[] ['a', 'b'] [1] list list [3, 2, 1] 3 [1, 2]\n")]
    [InlineData("class Named(list):\n    def __init__(self, name, items=()):\n        super().__init__(items)\n        self.name = name\nn = Named('n', [3, 1, 2])\nn.sort()\nprint(n, n.name, len(n), n.count(1), n.index(3), vars(n))", "[1, 2, 3] n 3 1 2 {'name': 'n'}\n")]
    [InlineData("class L(list):\n    def __init__(self, n):\n        self.n = n\nx = L(3)\nprint(x, x.n, len(x))\nx.extend([1, 2])\nprint(x, x[0])", "[] 3 0\n[1, 2] 1\n")]
