    [InlineData("class G(list):\n    def __getitem__(self, i):\n        return 'got ' + str(i)\n    def __len__(self):\n        return 100\n    def __iter__(self):\n        return iter(['it'])\n    def __contains__(self, x):\n        return True\ng = G([1, 2])\nprint(g[0], len(g), list(g), 5 in g, [v for v in g], bool(G()))", "got 0 100 ['it'] True ['it'] True\n")]
    [InlineData("class V(list):\n    def __add__(self, other):\n        return V(a + b for a, b in zip(self, other))\n    def __mul__(self, k):\n        return V(a * k for a in self)\n    __rmul__ = __mul__\n    def __eq__(self, other):\n        return list(self) == list(other) and 'eq'\nv = V([1, 2])\nprint(v + V([3, 4]), v * 3, 2 * v, v == [1, 2], type(v + v).__name__)", "[4, 6] [3, 6] [2, 4] eq V\n")]
    [InlineData("class Counter2(dict):\n    def __missing__(self, key):\n        return 0\nc = Counter2()\nc['a'] += 1\nc['a'] += 1\nprint(c, c['b'], 'b' in c, c.get('b'), len(c), isinstance(c, dict), type(c).__name__, c == {'a': 2})", "{'a': 2} 0 False None 1 True Counter2 True\n")]
    [InlineData("class AttrDict(dict):\n    def __getattr__(self, name):\n        try:\n            return self[name]\n        except KeyError:\n            raise AttributeError(name)\n    def __setattr__(self, name, value):\n        self[name] = value\na = AttrDict(x=1)\na.y = 2\nprint(a.x, a.y, a, sorted(a.keys()), dict(a), type(dict(a)).__name__, hasattr(a, 'z'))\na.z", "1 2 {'x': 1, 'y': 2} ['x', 'y'] {'x': 1, 'y': 2} dict False\n!AttributeError: z")]
    [InlineData("class Up(dict):\n    def __setitem__(self, k, v):\n        super().__setitem__(k.upper(), v)\nu = Up(a=1)\nu['b'] = 2\nu.update(c=3)\nu.setdefault('d', 4)\nprint(u, type(u.copy()).__name__, u | {'e': 5}, type(u | {'e': 5}).__name__)", "{'a': 1, 'B': 2, 'c': 3, 'd': 4} dict {'a': 1, 'B': 2, 'c': 3, 'd': 4, 'e': 5} dict\n")]
