    [InlineData("class Default(dict):\n    def __init__(self, factory, *args, **kw):\n        super().__init__(*args, **kw)\n        self.factory = factory\n    def __missing__(self, key):\n        self[key] = v = self.factory()\n        return v\nd = Default(list, x=[0])\nd['a'].append(1)\nd['a'].append(2)\nd['x'].append(3)\nprint(d, sorted(d), d.factory.__name__)", "{'x': [0, 3], 'a': [1, 2]} ['a', 'x'] list\n")]
    [InlineData("class S(list):\n    pass\nhash(S())", "!TypeError: unhashable type: 'S'")]
